--
-- Structure de la table `schulerdetail`
--

CREATE TABLE `schulerdetail` (
  `id` int(11) NOT NULL,
  `matelev` int(11) NOT NULL,
  `nomelev` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `preelev` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `datelev` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `niveauelev` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `anelev` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `sexelev` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `id_etab` int(11) NOT NULL,
  `statut` varchar(5) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `frais` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `remise` varchar(5) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `montant` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `date` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `heure` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `idempl` int(11) NOT NULL,
  `typerem` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

